let academyAudioContext=null;
function setVoiceMonitor(mode='ready',label=''){
  if(!voiceMonitor)return;
  voiceMonitor.classList.remove('is-ready','is-speaking','is-pending','is-off','is-error');
  voiceMonitor.classList.add(`is-${mode}`);
  const defaultLabel={ready:'Ton bereit',speaking:'Stimme läuft',pending:'Stimme startet',off:'Ton aus',error:'Tonfehler'}[mode]||'Ton bereit';
  if(voiceMonitorText)voiceMonitorText.textContent=label||defaultLabel;
}
async function unlockAcademyAudio(){
  try{
    const Ctx=window.AudioContext||window.webkitAudioContext;
    if(Ctx){academyAudioContext=academyAudioContext||new Ctx();if(academyAudioContext.state==='suspended')await academyAudioContext.resume()}
    if(window.speechSynthesis){speechSynthesis.resume();speechSynthesis.getVoices()}
    return true;
  }catch{return false}
}
let academySpeechPrimed=false;
function primeAcademySpeech(){
  if(academySpeechPrimed||!('speechSynthesis' in window))return;
  academySpeechPrimed=true;
  try{
    speechSynthesis.cancel();speechSynthesis.resume();
    const u=new SpeechSynthesisUtterance(' ');u.lang='de-DE';u.volume=.01;u.rate=1;
    u.onend=()=>{try{speechSynthesis.resume()}catch{}};speechSynthesis.speak(u);
  }catch{academySpeechPrimed=false}
}
async function playAcademyTestTone(){
  const ok=await unlockAcademyAudio();if(!ok||!academyAudioContext)throw new Error('AudioContext nicht verfügbar');
  return new Promise(resolve=>{const osc=academyAudioContext.createOscillator(),gain=academyAudioContext.createGain();osc.type='sine';osc.frequency.value=660;gain.gain.setValueAtTime(.0001,academyAudioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.09,academyAudioContext.currentTime+.03);gain.gain.exponentialRampToValueAtTime(.0001,academyAudioContext.currentTime+.28);osc.connect(gain).connect(academyAudioContext.destination);osc.start();osc.stop(academyAudioContext.currentTime+.3);osc.onended=resolve})
}
async function runAcademyAudioTuv(){
  const status=document.querySelector('#audioTuvStatus'),btn=document.querySelector('#runAudioTuv');if(!status)return;
  btn&&(btn.disabled=true);status.className='settings-note';status.textContent='Prüfung läuft: Testton und Testansage …';
  try{
    state.sound=true;soundBtn.textContent='🔊';document.querySelector('#modalSound').checked=true;saveSettings();
    setVoiceMonitor('pending','Audio-TÜV läuft');await playAcademyTestTone();
    const result=await speak('Dies ist ein Audiotest der KC FUTURA Academy.',{characterKey:state.coach});
    if(result?.error||result?.silent)throw new Error('Sprachausgabe konnte nicht gestartet werden');
    status.className='settings-note tuv-pass';status.textContent='BESTANDEN: Testton und Testansage wurden gestartet. Bitte bestätigen Sie zusätzlich, dass beides hörbar war.';setVoiceMonitor('ready','Ton geprüft');
  }catch(err){status.className='settings-note tuv-fail';status.textContent='NICHT BESTANDEN: '+(err?.message||'Audioausgabe nicht verfügbar');setVoiceMonitor('error','Tonfehler')}finally{btn&&(btn.disabled=false)}
}

