const AudioStore={
  dbName:'kc-futura-academy-audio',storeName:'recordings',db:null,
  open(){if(this.db)return Promise.resolve(this.db);return new Promise((resolve,reject)=>{const req=indexedDB.open(this.dbName,1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(this.storeName))db.createObjectStore(this.storeName,{keyPath:'key'})};req.onsuccess=()=>{this.db=req.result;resolve(this.db)};req.onerror=()=>reject(req.error)})},
  async get(key){try{const db=await this.open();const row=await new Promise((resolve,reject)=>{const r=db.transaction(this.storeName,'readonly').objectStore(this.storeName).get(key);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)});if(!row)return null;if(row.encrypted&&row.payload){const plain=await KCSecureStorage.decryptBytes(row.payload);return {...row,blob:new Blob([plain],{type:row.meta?.mime||'audio/webm'})}}return row}catch{return null}},
  async put(key,blob,meta={}){const db=await this.open();const bytes=await blob.arrayBuffer();const payload=await KCSecureStorage.encryptBytes(bytes,'VOICE_RECORDING');const row={key,encrypted:true,payload,meta:{...meta,mime:blob.type||meta.mime||'audio/webm'},updatedAt:new Date().toISOString()};return new Promise((resolve,reject)=>{const r=db.transaction(this.storeName,'readwrite').objectStore(this.storeName).put(row);r.onsuccess=()=>resolve(true);r.onerror=()=>reject(r.error)})},
  async remove(key){try{const db=await this.open();return await new Promise((resolve,reject)=>{const r=db.transaction(this.storeName,'readwrite').objectStore(this.storeName).delete(key);r.onsuccess=()=>resolve(true);r.onerror=()=>reject(r.error)})}catch{return false}}
};

async function hashText(value){
  const bytes=new TextEncoder().encode(String(value||'').trim());
  const digest=await crypto.subtle.digest('SHA-256',bytes);
  return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('');
}
function saveElevenConfig(){
  set('localStorage',ELEVEN_CONFIG_KEY,JSON.stringify(elevenConfig));
  window.KCVoiceProvider?.configure({...elevenConfig,provider:state.voiceProvider});
}
function voiceIdFor(character){const map=elevenConfig.voiceIds?.[state.voiceProvider]||elevenConfig.voiceIds||{};return String(map?.[character]||'').trim()}
async function voiceAudioState(dialog){
  if(!dialog)return {kind:'missing',label:'Kein Dialog ausgewählt'};
  const existing=await AudioStore.get(dialog.key);
  if(!existing)return {kind:'missing',label:'Noch keine feste Sprachdatei vorhanden'};
  const currentHash=await hashText(dialog.text);
  const storedHash=existing.meta?.textHash||await hashText(existing.meta?.text||'');
  return storedHash===currentHash?{kind:'current',label:'Stimme aktuell und gespeichert',existing}:{kind:'stale',label:'Text geändert – Stimme neu erzeugen',existing};
}
async function generateElevenAudio(dialog,{previewOnly=false}={}){
  if(!dialog)throw new Error('Kein Dialog ausgewählt.');
  const voiceId=voiceIdFor(dialog.character);
  const ps=elevenConfig.providerSettings?.[state.voiceProvider]||{};const blob=await window.KCVoiceProvider.generate({provider:state.voiceProvider,text:dialog.text,voiceId,modelId:ps.modelId||elevenConfig.modelId,outputFormat:ps.outputFormat||elevenConfig.outputFormat,instructions:ps.instructions||''});
  if(previewOnly){const url=URL.createObjectURL(blob);const audio=new Audio(url);audio.onended=()=>URL.revokeObjectURL(url);audio.onerror=()=>URL.revokeObjectURL(url);await audio.play();return blob}
  const textHash=await hashText(dialog.text);
  await AudioStore.put(dialog.key,blob,{character:dialog.character,text:dialog.text,textHash,provider:state.voiceProvider,voiceId,modelId:(elevenConfig.providerSettings?.[state.voiceProvider]?.modelId||elevenConfig.modelId),generatedAt:new Date().toISOString(),mime:blob.type||'audio/mpeg'});
  return blob;
}
async function autoRegenerateDialog(dialogKey){
  if(!['elevenlabs','openai','azure'].includes(state.voiceProvider)||!elevenConfig.autoGenerate||!window.KCVoiceProvider?.isConfigured())return;
  const dialog=buildDialogRegistry().find(x=>x.key===dialogKey);if(!dialog||!voiceIdFor(dialog.character))return;
  try{await generateElevenAudio(dialog)}catch(err){console.warn('Automatische Sprachaktualisierung nicht möglich',err)}
}

async function ensureSpeechReady(){
  if(!('speechSynthesis' in window))return false;
  try{speechSynthesis.cancel();speechSynthesis.resume()}catch{}
  if(availableVoices().length)return true;
  await new Promise(resolve=>{
    let done=false;const finish=()=>{if(done)return;done=true;resolve()};
    const timer=setTimeout(finish,900);
    const handler=()=>{clearTimeout(timer);speechSynthesis.removeEventListener?.('voiceschanged',handler);finish()};
    speechSynthesis.addEventListener?.('voiceschanged',handler,{once:true});
    try{speechSynthesis.getVoices()}catch{}
  });
  return true;
}
const VoiceCore={
  version:VOICE_CORE_VERSION,
  activeResolve:null,
  activeTimer:null,
  activeUtterance:null,
  activeAudio:null,
  activeObjectUrl:null,
  token:0,
  pickVoice(characterKey){
    const voices=availableVoices();
    if(!voices.length)return null;
    const profile=voiceProfiles[characterKey]||voiceProfiles[state.coach]||voiceProfiles.laura;
    const femaleHints=/female|frau|anna|katja|petra|helena|google deutsch|vicki|amala|seraphina/i;
    const maleHints=/male|mann|stefan|markus|hans|conrad|martin|daniel|killian|yannick/i;
    const seniorHints=/senior|older|alt|grossvater|grandpa|hans|conrad|martin/i;
    let preferred=voices.filter(v=>profile.gender==='female'?femaleHints.test(v.name):maleHints.test(v.name));
    if(profile.age==='senior'){
      const senior=preferred.filter(v=>seniorHints.test(v.name));
      if(senior.length)preferred=senior;
    }
    const pool=preferred.length?preferred:voices;
    if(characterKey===state.coach){
      const idx=state.voice==='two'?1:0;
      const chosen=pool[Math.min(idx,pool.length-1)]||voices[0];
      this.lastCoachVoiceName=chosen?.name||'';
      return chosen;
    }
    let usable=pool;
    if(characterKey==='herr_becker'&&state.coach==='marc'&&this.lastCoachVoiceName){
      const different=pool.filter(v=>v.name!==this.lastCoachVoiceName);
      if(different.length)usable=different;
    }
    const order=['laura','marc','frau_schmitt','lukas','michael','sabrina','leo','herr_becker','dr_brinkmann','julia','herr_koslowski','eugen','gisela','kalle','hannes','detlef'];
    const idx=Math.max(0,order.indexOf(characterKey));
    return usable[idx%usable.length]||voices[idx%voices.length]||voices[0];
  },
  stop(){
    this.token++;
    if(this.activeTimer){clearTimeout(this.activeTimer);this.activeTimer=null}
    try{speechSynthesis?.cancel()}catch{}
    if(this.activeAudio){try{this.activeAudio.pause();this.activeAudio.currentTime=0}catch{}this.activeAudio=null}
    if(this.activeObjectUrl){try{URL.revokeObjectURL(this.activeObjectUrl)}catch{}this.activeObjectUrl=null}
    if(this.activeResolve){const r=this.activeResolve;this.activeResolve=null;r({stopped:true})}
    this.activeUtterance=null;
    document.querySelectorAll('.reading').forEach(el=>el.classList.remove('reading'));
    setVoiceMonitor(state.sound?'ready':'off',state.sound?'Ton bereit':'Ton aus');
  },
  async speak(raw,{highlight=null,characterKey=null,audioKey=null}={}){
    this.stop();
    const token=this.token;
    const t=text(raw);state.lastSpeech=t;repeatBtn.hidden=false;
    if(state.paused||!state.sound){setVoiceMonitor('off',state.sound?'Pausiert':'Ton aus');return {silent:true}}
    await unlockAcademyAudio();setVoiceMonitor('pending',`${chars[characterKey||state.coach]?.name||'Stimme'} startet`);
    if(audioKey&&state.voiceProvider!=='system'){
      const savedAudio=await AudioStore.get(audioKey);
      if(token!==this.token||state.paused)return {stopped:true};
      if(savedAudio?.blob){
        return new Promise(resolve=>{
          const token=this.token;this.activeResolve=resolve;const url=URL.createObjectURL(savedAudio.blob);const audio=new Audio(url);this.activeAudio=audio;this.activeObjectUrl=url;
          const finish=result=>{highlight?.classList.remove('reading');if(this.activeResolve===resolve)this.activeResolve=null;if(this.activeAudio===audio)this.activeAudio=null;if(this.activeObjectUrl===url){URL.revokeObjectURL(url);this.activeObjectUrl=null}setVoiceMonitor(result?.error?'error':(state.sound?'ready':'off'),result?.error?'Tonfehler':(state.sound?'Ton bereit':'Ton aus'));resolve(result||{done:true,recorded:true})};
          audio.onplay=()=>{if(token===this.token&&!state.paused){highlight?.classList.add('reading');setVoiceMonitor('speaking',`${chars[characterKey||state.coach]?.name||'Stimme'} spricht`)}};audio.onended=()=>finish();audio.onerror=()=>finish({error:true});
          audio.play().catch(()=>finish({error:true}));
        });
      }
    }
    if(!('speechSynthesis'in window)){setVoiceMonitor('error','Keine Gerätestimme');return {silent:true}};
    await ensureSpeechReady();
    return new Promise(resolve=>{
      this.activeResolve=resolve;
      const key=characterKey||state.coach;
      const profile=voiceProfiles[key]||voiceProfiles[state.coach]||voiceProfiles.laura;
      let settled=false,started=false,retries=0,startWatch=null;
      const finish=result=>{
        if(settled)return;settled=true;
        if(startWatch)clearTimeout(startWatch);
        highlight?.classList.remove('reading');
        if(this.activeResolve===resolve)this.activeResolve=null;
        setVoiceMonitor(result?.error?'error':(state.sound?'ready':'off'),result?.error?'Tonfehler':(state.sound?'Ton bereit':'Ton aus'));
        if(token===this.token)resolve(result||{done:true});
      };
      const launch=()=>{
        if(token!==this.token||state.paused){finish({stopped:true});return}
        try{speechSynthesis.resume()}catch{}
        const u=new SpeechSynthesisUtterance(`  ${ttsText(t)}`);
        u.lang='de-DE';u.rate=Math.max(.6,Math.min(1.3,profile.rate*state.speechRate));u.pitch=profile.pitch;u.volume=Math.max(.1,Math.min(1,profile.volume*(state.volume/10)));
        const v=this.pickVoice(key);if(v)u.voice=v;
        this.activeUtterance=u;started=false;
        u.onstart=()=>{started=true;if(startWatch)clearTimeout(startWatch);if(token===this.token&&!state.paused){highlight?.classList.add('reading');setVoiceMonitor('speaking',`${chars[key]?.name||'Stimme'} spricht`)}};
        u.onend=()=>finish({done:true});
        u.onerror=()=>{if(!started&&retries<1){retries++;setTimeout(launch,180)}else finish({error:true})};
        try{speechSynthesis.speak(u)}catch{if(retries<1){retries++;setTimeout(launch,220)}else finish({error:true});return}
        // Safari/iPad meldet onstart nicht immer zuverlässig: laufende Sprache nicht vorschnell abbrechen.
        setTimeout(()=>{if(!settled&&token===this.token&&!state.paused&&(speechSynthesis.speaking||speechSynthesis.pending)){started=true;highlight?.classList.add('reading');setVoiceMonitor('speaking',`${chars[key]?.name||'Stimme'} spricht`)}},180);
        startWatch=setTimeout(()=>{if(settled||token!==this.token||state.paused)return;try{speechSynthesis.resume()}catch{};if(speechSynthesis.speaking||speechSynthesis.pending){started=true;highlight?.classList.add('reading');setVoiceMonitor('speaking',`${chars[key]?.name||'Stimme'} spricht`);return}if(retries<1){retries++;launch()}else finish({error:true})},2600);
      };
      this.activeTimer=setTimeout(()=>{this.activeTimer=null;launch()},SPEECH_LEAD_MS);
    });
  }
};
function stopSpeech(){VoiceCore.stop()}
function speak(raw,opts={}){return VoiceCore.speak(raw,opts)}
async function runQuizCountdown(){
  const host=document.querySelector('#quizCountdown');if(!host||!state.countdownEnabled)return;
  for(const n of [3,2,1]){if(state.view!=='scene'||state.paused)return;host.innerHTML=`<span>${n}</span>${n===1?`<small>${settingLabel('Jetzt Antwort wählen!','Jetzt Antwort wählen!')}</small>`:''}`;host.classList.add('show');await new Promise(r=>setTimeout(r,520));host.classList.remove('show');await new Promise(r=>setTimeout(r,70))}
  host.textContent='';
}
async function speakChoices(question,choiceButtons){
  await speak(question,{highlight:document.querySelector('.question-title'),characterKey:state.coach});
  for(const btn of choiceButtons){if(state.view!=='scene'||state.paused)return;await speak(btn.textContent,{highlight:btn,characterKey:state.coach})}
  if(state.quizShorten)return;
  await runQuizCountdown();
}


function moduleStats(m){const x=SceneCore.normalize('',m);return {scenes:x.sceneCount,questions:x.questionCount,estimatedMinutes:x.estimatedMinutes,duration:`ca. ${x.estimatedMinutes} Minuten`,scope:`${x.sceneCount} Lernschritte · ${x.questionCount} Wissensfragen`}}

function setProgress(cur,total,txt){bar.style.width=`${total?Math.round(cur/total*100):0}%`;label.textContent=txt}
function settingLabel(du,sie){return state.address==='sie'?sie:du}
function setView(view){state.view=view;backBtn.disabled=view==='welcome';sceneProgress.hidden=view!=='scene';updateSceneProgress()}
function updateSceneProgress(){
  if(state.view!=='scene'||!state.module){sceneProgress.hidden=true;sceneProgress.innerHTML='';return}
  const m=modules[state.module];sceneProgress.hidden=false;
  sceneProgress.innerHTML=m.scenes.map((_,i)=>`<button class="scene-dot ${i<state.step?'done':i===state.step?'active':''}" data-scene="${i}" title="Zu Szene ${i+1} wechseln" aria-label="Zu Szene ${i+1} wechseln">${i<state.step?'✓':i+1}</button>`).join('')+`<small>Szene ${state.step+1}/${m.scenes.length}</small>`;
  sceneProgress.querySelectorAll('[data-scene]').forEach(btn=>btn.onclick=()=>jumpToScene(Number(btn.dataset.scene)));
}
function updateTime(){
  const now=new Date();dateDisplay.textContent=now.toLocaleDateString('de-DE');clockDisplay.textContent=now.toLocaleTimeString('de-DE');
  const end=state.paused&&state.pausedAt?state.pausedAt:Date.now();const ms=Math.max(0,end-state.startTime-state.totalPaused);const sec=Math.floor(ms/1000);const h=String(Math.floor(sec/3600)).padStart(2,'0');const m=String(Math.floor(sec%3600/60)).padStart(2,'0');const s=String(sec%60).padStart(2,'0');elapsedDisplay.textContent=`Laufzeit ${h}:${m}:${s}`;
}
setInterval(updateTime,500);updateTime();
function jumpToScene(target){
  if(!state.module||!Number.isInteger(target))return;
  const m=modules[state.module];if(target<0||target>=m.scenes.length||target===state.step)return;
  const prompt=settingLabel(`Möchtest du wirklich zu Szene ${target+1} wechseln?`,`Möchten Sie wirklich zu Szene ${target+1} wechseln?`);
  if(!window.confirm(prompt))return;
  stopSpeech();state.paused=false;pauseBtn.textContent='⏸ Pause';state.step=target;showScene();
}
function togglePause(){
  if(!state.paused){
    state.paused=true;state.pausedAt=Date.now();
    stopSpeech();
    pauseBtn.textContent='▶ Fortsetzen';
    document.body.classList.add('academy-paused');
    showPauseOverlay();
  }else{
    state.paused=false;state.totalPaused+=Date.now()-state.pausedAt;state.pausedAt=0;
    pauseBtn.textContent='⏸ Pause';document.body.classList.remove('academy-paused');
    document.querySelector('#pauseOverlay')?.remove();
    if(state.view==='scene'&&state.module){showScene();return}
    if(state.view==='personal'){showPersonalWelcome();return}
    if(state.view==='overview'&&state.module){overview(state.module);return}
    if(state.lastSpeech)speak(state.lastSpeech,{characterKey:currentSpeakerKey()});
  }
}
function currentSpeakerKey(){
  if(state.view==='scene'&&state.module){return modules[state.module].scenes[state.step]?.key||state.coach}
  return state.coach;
}
function showPauseOverlay(){
  document.querySelector('#pauseOverlay')?.remove();
  const el=document.createElement('div');el.id='pauseOverlay';el.className='pause-overlay';
  el.innerHTML=`<div><div class="pause-icon">⏸</div><h2>Academy pausiert</h2><p>${settingLabel('Klicke auf „Fortsetzen“, wenn du bereit bist.','Klicken Sie auf „Fortsetzen“, wenn Sie bereit sind.')}</p><button id="resumeOverlay" class="primary">▶ Fortsetzen</button></div>`;
  document.body.appendChild(el);document.querySelector('#resumeOverlay').onclick=togglePause;
}
function goBack(){stopSpeech();if(state.view==='personal')welcome();else if(state.view==='home')welcome();else if(state.view==='overview')home();else if(state.view==='scene'){if(state.step>0){state.step--;showScene()}else overview(state.module)}else if(state.view==='finish')home()}

async function checkParticipantName(name){try{return await window.KCSupabaseAdapter?.findParticipantNames?.(name)||[]}catch(e){console.warn('Dublettenprüfung nicht verfügbar',e);return []}}
function openParticipantChoice(name,matches=[]){pendingParticipantName=name;const modal=document.querySelector('#participantChoiceModal'),count=document.querySelector('#participantDuplicateCount');count.textContent=matches.length?`Den Namen „${name}“ gibt es bereits. Bist du das?`:`Der Name „${name}“ ist noch frei.`;document.querySelector('#participantRecoveryArea').hidden=true;document.querySelector('#participantChoiceError').textContent='';modal.hidden=false;document.body.classList.add('modal-open')}
function closeParticipantChoice(){document.querySelector('#participantChoiceModal').hidden=true;document.body.classList.remove('modal-open')}
function chooseDifferentParticipantName(){closeParticipantChoice();const modal=document.querySelector('#firstRunModal');modal.hidden=false;document.body.classList.add('modal-open');const input=document.querySelector('#firstRunName');input.value='';document.querySelector('#firstRunHint').textContent='Bitte einen anderen Vornamen eingeben.';document.querySelector('#firstRunContinue').disabled=true;setTimeout(()=>input.focus(),30)}
async function createNewParticipant(){const code=participantCode(),profile={id:crypto.randomUUID(),displayName:pendingParticipantName,recoveryCode:code,createdAt:new Date().toISOString(),installationId:window.KCSupabaseAdapter?.diagnostics?.().installationId||''};saveParticipantProfile(profile);closeParticipantChoice();const modal=document.querySelector('#participantCodeModal');document.querySelector('#participantCodeValue').textContent=code;modal.hidden=false;document.body.classList.add('modal-open');await window.KCSupabaseAdapter?.registerParticipant?.(profile,await sha256Text(code)).catch(()=>{})}
function showRecoveryEntry(){document.querySelector('#participantRecoveryArea').hidden=false;document.querySelector('#participantRecoveryCode').focus()}
async function claimExistingParticipant(){const code=document.querySelector('#participantRecoveryCode').value.trim().toUpperCase();if(!code){document.querySelector('#participantChoiceError').textContent='Bitte Wiederherstellungscode eingeben.';return}try{const result=await window.KCSupabaseAdapter?.claimParticipant?.(pendingParticipantName,await sha256Text(code));if(!result?.id)throw new Error('Name oder Wiederherstellungscode nicht gefunden.');saveParticipantProfile({id:result.id,displayName:result.display_name||pendingParticipantName,recoveryCode:code,createdAt:result.created_at||new Date().toISOString(),installationId:window.KCSupabaseAdapter?.diagnostics?.().installationId||''});closeParticipantChoice();showPersonalWelcome()}catch(e){document.querySelector('#participantChoiceError').textContent=e.message||'Lernstand konnte nicht übernommen werden.'}}
