async function beginParticipant(name){const clean=String(name||'').trim();if(participantProfile?.displayName&&participantProfile.displayName.toLowerCase()===clean.toLowerCase()){state.name=participantProfile.displayName;set('sessionStorage','kcAcademyName',state.name);showPersonalWelcome();return}const matches=await checkParticipantName(clean);pendingParticipantName=clean;if(matches.length){openParticipantChoice(clean,matches);return}await createNewParticipant()}

