  screen.querySelectorAll('[data-open-module]').forEach(card=>{card.onclick=e=>{if(e.target.closest('button'))return;overview(card.dataset.openModule)};card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();overview(card.dataset.openModule)}}});
