function setCloudCheck(key,state,label=''){const el=document.querySelector(`[data-check="${key}"]`);if(!el)return;el.className=state==='ok'?'check-ok':state==='error'?'check-error':state==='working'?'check-working':'';const icon=state==='ok'?'✓':state==='error'?'✕':state==='working'?'…':'○';el.textContent=`${icon} ${label||el.textContent.replace(/^[✓✕…○]\s*/,'')}`}
function refreshSupabaseControls(){const url=document.querySelector('#supabaseProjectUrl'),key=document.querySelector('#supabasePublishableKey'),save=document.querySelector('#supabaseSave'),test=document.querySelector('#supabaseTest'),sync=document.querySelector('#supabaseSyncNow');if(url&&!url.value.trim())url.value=DEFAULT_SUPABASE_URL;const hasUrl=Boolean(url?.value.trim()),hasKey=Boolean(key?.value.trim());setCloudCheck('url',hasUrl?'ok':'error','Projekt-URL');setCloudCheck('key',hasKey?'ok':'','Publishable Key');if(save)save.disabled=!(hasUrl&&hasKey);if(test)test.disabled=!(hasUrl&&hasKey);const d=window.KCSupabaseAdapter?.diagnostics?.()||{};if(sync)sync.disabled=!(d.authenticated&&d.lastResult?.connectionTest===true);}
function supabaseConfigToForm(){const c=window.KCSupabaseAdapter?.config||{};const q=id=>document.querySelector(id);if(q('#supabaseProjectUrl'))q('#supabaseProjectUrl').value=c.projectUrl||DEFAULT_SUPABASE_URL;if(q('#supabasePublishableKey'))q('#supabasePublishableKey').value=c.publishableKey||DEFAULT_SUPABASE_KEY||'';if(q('#supabaseEnabled'))q('#supabaseEnabled').checked=Boolean(c.enabled);if(q('#supabaseAutoSync'))q('#supabaseAutoSync').checked=c.autoSync!==false;if(q('#supabaseOfflineAllowed'))q('#supabaseOfflineAllowed').checked=c.offlineAllowed!==false;if(q('#supabaseSyncInterval'))q('#supabaseSyncInterval').value=String(c.syncIntervalSeconds||60);q('#supabasePublishableKey')?.addEventListener('input',refreshSupabaseControls);q('#supabaseProjectUrl')?.addEventListener('input',refreshSupabaseControls);const toggle=q('#supabaseKeyToggle');if(toggle)toggle.onclick=()=>{const i=q('#supabasePublishableKey');i.type=i.type==='password'?'text':'password';toggle.textContent=i.type==='password'?'👁':'🙈'};refreshSupabaseControls()}
function supabaseMessage(text,kind=''){const e=document.querySelector('#supabaseAdminMessage');if(!e)return;e.textContent=text;e.className='settings-note '+(kind?`sync-status-${kind}`:'')}
function readSupabaseForm(){return {projectUrl:document.querySelector('#supabaseProjectUrl')?.value.trim()||DEFAULT_SUPABASE_URL,publishableKey:document.querySelector('#supabasePublishableKey')?.value.trim()||DEFAULT_SUPABASE_KEY||'',enabled:Boolean(document.querySelector('#supabaseEnabled')?.checked),autoSync:Boolean(document.querySelector('#supabaseAutoSync')?.checked),offlineAllowed:Boolean(document.querySelector('#supabaseOfflineAllowed')?.checked),syncIntervalSeconds:Number(document.querySelector('#supabaseSyncInterval')?.value)||60}}
function showSupabaseTestDetails(r){const host=document.querySelector('#supabaseTestDetails');if(!host)return;host.hidden=false;const step=(ok,label,detail='')=>`<div class="cloud-test-row ${ok?'ok':'fail'}"><b>${ok?'✓':'✕'} ${esc(label)}</b><span>${esc(String(detail||''))}</span></div>`;host.innerHTML=[step(r.authOk,'Anonyme Anmeldung',r.userId?`Benutzer-ID ${r.userId}`:'nicht bestätigt'),step(r.dbOk,'Datenbank erreichbar',r.table||''),step(r.rlsOk,'RLS-Zugriff',r.rlsMessage||''),step(r.writeOk,'Testdatensatz schreiben',r.writeMessage||''),step(r.readOk,'Testdatensatz lesen',r.readMessage||''),step(r.cleanupOk,'Testdatensatz bereinigen',r.cleanupMessage||''),step(r.ok,'Synchronisation bereit',r.latencyMs!=null?`${r.latencyMs} ms`:'')].join('')}
async function saveSupabaseForm(){window.KCSupabaseAdapter?.configure(readSupabaseForm());updateDbStatus();supabaseMessage('Verbindung verschlüsselt gespeichert. Jetzt bitte testen.','ok');refreshSupabaseControls();renderAdminSystem()}
async function testSupabaseConnection(){supabaseMessage('Verbindung, Anmeldung, RLS sowie Schreiben und Lesen werden geprüft …','warn');['auth','db','rls','sync'].forEach(k=>setCloudCheck(k,'working'));try{window.KCSupabaseAdapter?.configure({...readSupabaseForm(),enabled:true});const r=await window.KCSupabaseAdapter.testConnection({full:true});showSupabaseTestDetails(r);setCloudCheck('auth',r.authOk?'ok':'error','Anonyme Anmeldung');setCloudCheck('db',r.dbOk?'ok':'error','Datenbank');setCloudCheck('rls',r.rlsOk?'ok':'error','RLS');setCloudCheck('sync',r.ok?'ok':'error','Synchronisation');if(!r.ok)throw new Error(r.message||'Mindestens ein Prüfschritt ist fehlgeschlagen.');document.querySelector('#supabaseEnabled').checked=true;window.KCSupabaseAdapter.configure(readSupabaseForm());supabaseMessage(`Verbindung hergestellt. Future Academy ist online bereit (${r.latencyMs} ms).`,'ok');updateDbStatus();refreshSupabaseControls();renderAdminSystem();renderPerformanceGauges();renderCloudDeviceMonitor()}catch(e){supabaseMessage('Verbindung fehlgeschlagen: '+e.message,'error');updateDbStatus();refreshSupabaseControls()}}
async function syncSupabaseNow(){supabaseMessage('Synchronisation läuft …','warn');try{window.KCSupabaseAdapter?.configure({...readSupabaseForm(),enabled:true});const r=await window.KCSupabaseAdapter.sync();if(!r.ok&&r.reason)throw new Error(r.message||r.reason);supabaseMessage(`Synchronisiert: ${r.sent||0} übertragen, ${r.pending||0} ausstehend.`,'ok');setCloudCheck('sync','ok','Synchronisation');updateDbStatus();renderAdminSystem();renderPerformanceGauges();renderCloudDeviceMonitor()}catch(e){supabaseMessage('Synchronisation fehlgeschlagen: '+e.message,'error');setCloudCheck('sync','error','Synchronisation');updateDbStatus()}}

function gaugeMeta(kind,value){
  const n=Math.max(0,Number(value)||0);
  if(kind==='local'){const score=Math.min(1,n/250);return {deg:Math.round(score*270),status:n>=140?'sehr schnell':n>=70?'gut':'langsam',cls:n>=140?'speed-status-fast':n>=70?'speed-status-medium':'speed-status-slow'}}
  const score=Math.max(0,Math.min(1,1-(n-80)/1120));return {deg:Math.round(score*270),status:n<=350?'sehr gut':n<=750?'gut':'langsam',cls:n<=350?'speed-status-fast':n<=750?'speed-status-medium':'speed-status-slow'}
}
function speedGaugeCard({kind,title,value,unit,statusDetail,rows=[]}){const m=gaugeMeta(kind,value);return `<article class="speed-gauge-card"><div class="speed-gauge" style="--gauge:${m.deg}deg" role="img" aria-label="${esc(title)} ${esc(String(value))} ${esc(unit)}"><div class="speed-gauge-value"><b>${esc(String(value))}</b><small>${esc(unit)}</small></div></div><div class="speed-gauge-copy"><h4>${esc(title)}</h4><p class="${m.cls}">${esc(m.status)}</p><p>${esc(statusDetail||'')}</p><dl>${rows.map(([a,b])=>`<dt>${esc(a)}</dt><dd>${esc(String(b))}</dd>`).join('')}</dl></div></article>`}
async function renderPerformanceGauges(){const host=document.querySelector('#performanceGauges');if(!host)return;host.innerHTML='<p class="settings-note">Geschwindigkeit wird gemessen …</p>';let local={opsPerSecond:0,writeMs:'—',readMs:'—',totalMs:'—'};try{await window.KCSecureStorage?.ready;local=await window.KCSecureStorage?.benchmark?.()||local}catch(e){console.warn('IndexedDB benchmark failed',e)}const d=window.KCSupabaseAdapter?.diagnostics?.()||{};const lr=d.lastResult||{};const latency=Number(lr.latencyMs||lr.durationMs||0);const cloudValue=latency||0;host.innerHTML=speedGaugeCard({kind:'local',title:'IndexedDB',value:local.opsPerSecond||0,unit:'Vorgänge/s',statusDetail:'Lokaler verschlüsselter Speicher',rows:[['Schreiben',`${local.writeMs} ms`],['Lesen',`${local.readMs} ms`],['Gesamt',`${local.totalMs} ms`]]})+speedGaugeCard({kind:'cloud',title:'Supabase Cloud',value:cloudValue||'—',unit:cloudValue?'ms':'kein Messwert',statusDetail:d.authenticated?'Online und angemeldet':'Noch kein aktueller Verbindungstest',rows:[['Letzte Übertragung',lr.sent??0],['Datensätze/s',lr.recordsPerSecond??'—'],['Ausstehend',lr.pending??0],['Letzte Aktivität',lr.at?new Date(lr.at).toLocaleString('de-DE'):'—']]})}
function deviceIcon(name=''){const n=String(name).toLowerCase();if(n.includes('ipad')||n.includes('iphone'))return '📱';if(n.includes('android'))return '📱';if(n.includes('windows')||n.includes('pc')||n.includes('mac'))return '💻';return '🖥️'}
async function renderCloudDeviceMonitor(){const list=document.querySelector('#cloudDeviceList'),counters=document.querySelector('#cloudSyncCounters'),nameInput=document.querySelector('#cloudDeviceName');if(!list||!counters)return;const a=window.KCSupabaseAdapter,d=a?.diagnostics?.()||{},st=d.stats||{},lr=d.lastResult||{};if(nameInput&&!nameInput.value)nameInput.value=d.deviceName||'';counters.innerHTML=`<article class="cloud-counter"><b>${Number(st.uploaded||0)}</b><span>Hochgeladen</span></article><article class="cloud-counter"><b>${Number(st.downloaded||0)}</b><span>Heruntergeladen</span></article><article class="cloud-counter"><b>${Number(lr.pending||0)}</b><span>Warteschlange</span></article><article class="cloud-counter"><b>${st.lastSync?esc(new Date(st.lastSync).toLocaleTimeString('de-DE')):'—'}</b><span>Letzte Synchronisation</span></article>`;list.innerHTML='<p class="settings-note">Geräte werden geladen …</p>';let devices=[];try{if(d.authenticated)devices=await a.listDevices()}catch(e){console.warn('Device list failed',e)}if(!devices.length){devices=[{installation_id:d.installationId,client_created_at:st.lastHeartbeat||new Date().toISOString(),academy_version:ACADEMY_VERSION,metadata:{device_name:d.deviceName||'Dieses Gerät',device_type:d.deviceName||'',online:d.online}}]}list.innerHTML=devices.map(row=>{const m=row.metadata||{},seen=row.client_created_at||m.last_seen||'',age=seen?Date.now()-new Date(seen).getTime():Infinity,online=age<120000&&d.online;return `<article class="cloud-device-card"><span class="cloud-device-icon">${deviceIcon(m.device_type||m.device_name)}</span><div class="cloud-device-copy"><b>${esc(m.device_name||'Unbenanntes Gerät')}</b><small>${esc(row.academy_version||'')} · ${seen?`zuletzt ${esc(new Date(seen).toLocaleString('de-DE'))}`:'kein Kontakt'}</small><small>${esc(row.installation_id||'')}</small></div><span class="cloud-device-state ${online?'':'offline'}">${online?'Online':'Zuletzt gesehen'}</span></article>`}).join('')}
function renderAdminSystem(){const host=document.querySelector('#adminSystemStatus');if(!host)return;const d=window.KCSupabaseAdapter?.diagnostics?.()||{},lr=d.lastResult||{};host.innerHTML=`<article><b>IndexedDB</b><span class="status-ok">verbunden</span><small>Verschlüsselter Secure Storage aktiv</small></article><article><b>Supabase</b><span class="${d.enabled&&d.configured&&d.authenticated?'status-ok':'status-warn'}">${d.enabled&&d.configured?(d.online?(d.authenticated?'verbunden':'bereit'):'offline'):'noch nicht eingerichtet'}</span><small>${d.authenticated?'Anonyme Sitzung aktiv':d.configured?'Anmeldung erfolgt beim ersten Test':'Projekt-URL und Publishable Key erforderlich'}</small></article><article><b>Synchronisation</b><span>${lr.at?esc(new Date(lr.at).toLocaleString('de-DE')):'noch nicht ausgeführt'}</span><small>${lr.sent||0} zuletzt übertragen · ${lr.pending||0} ausstehend</small></article><article><b>Cloud-Benutzer</b><span>${d.userId?esc(d.userId):'—'}</span><small>Installation ${esc(d.installationId||'—')}</small></article><article><b>Voice Provider</b><span>${esc(state.voiceProvider)}</span></article><article><b>Version</b><span>${ACADEMY_VERSION}</span></article>`;supabaseConfigToForm();const b=id=>document.querySelector(id);if(b('#supabaseSave'))b('#supabaseSave').onclick=saveSupabaseForm;if(b('#supabaseTest'))b('#supabaseTest').onclick=testSupabaseConnection;if(b('#supabaseSyncNow'))b('#supabaseSyncNow').onclick=syncSupabaseNow;if(b('#performanceRefresh'))b('#performanceRefresh').onclick=renderPerformanceGauges;if(b('#cloudDeviceRefresh'))b('#cloudDeviceRefresh').onclick=()=>{window.KCSupabaseAdapter?.registerDevice?.().catch(()=>{});renderCloudDeviceMonitor()};if(b('#cloudDeviceSave'))b('#cloudDeviceSave').onclick=async()=>{const n=b('#cloudDeviceName')?.value||'';window.KCSupabaseAdapter?.setDeviceName?.(n);await window.KCSupabaseAdapter?.registerDevice?.().catch(()=>{});renderCloudDeviceMonitor()};renderPerformanceGauges();renderCloudDeviceMonitor()}
function renderDiagnostics(){const host=document.querySelector('#diagnosticsContent');if(!host)return;const d=window.KCSupabaseAdapter?.diagnostics?.()||{};host.innerHTML=`<article><b>Lokale Daten</b><span class="status-ok">bereit</span><small>Verschlüsselter Speicher aktiv</small></article><article><b>Online-Verbindung</b><span class="${d.enabled&&d.configured&&d.online?'status-ok':'status-warn'}">${d.enabled&&d.configured?(d.online?'bereit':'offline'):'nicht eingerichtet'}</span><small>${d.authenticated?'Automatische Anmeldung aktiv':d.configured?'Anmeldung wird automatisch versucht':'Supportbericht kann trotzdem erstellt werden'}</small></article><article><b>Ton</b><span>${state.sound?'aktiv':'aus'}</span><small>Lautstärke ${state.volume}/10</small></article><article><b>Version</b><span>${ACADEMY_VERSION}</span><small>KC FUTURA Academy</small></article>`}
