function closeEpisodeEditor(){document.querySelector('#episodeEditorModal').hidden=true;document.body.classList.remove('modal-open')}
function renderEpisodeEditor(){const list=document.querySelector('#episodeEditorList');if(!adminModuleKey)adminModuleKey=SceneCore.catalog()[0]?.id||'';list.innerHTML=SceneCore.catalog().map(m=>`<button class="episode-editor-module ${m.id===adminModuleKey?'selected':''}" data-admin-module="${m.id}"><b>Folge ${m.episode}: ${esc(m.title)}</b><small>${m.sceneCount} Szenen · ${m.ready?'spielbar':'vorbereitet'}</small></button>`).join('');list.querySelectorAll('[data-admin-module]').forEach(b=>b.onclick=()=>{adminModuleKey=b.dataset.adminModule;adminSceneIndex=0;renderEpisodeEditor()});const m=modules[adminModuleKey],sceneList=document.querySelector('#episodeEditorScenes'),editor=document.querySelector('#episodeEditorForm');if(!m){editor.innerHTML='';return}sceneList.innerHTML=(m.scenes||[]).map((sc,i)=>`<button class="episode-editor-scene ${i===adminSceneIndex?'selected':''}" data-admin-scene="${i}">Szene ${i+1}: ${esc(sc.who||'Ohne Sprecher')}</button>`).join('')||'<p>Für diese Folge sind noch keine Szenen angelegt.</p>';sceneList.querySelectorAll('[data-admin-scene]').forEach(b=>b.onclick=()=>{adminSceneIndex=Number(b.dataset.adminScene);renderEpisodeEditor()});const sc=m.scenes?.[adminSceneIndex];if(!sc){editor.innerHTML='<p>Keine Szene zur Bearbeitung vorhanden.</p>';return}const choices=(sc.choices||[]).map(x=>`${x[1]}|${x[0]}`).join('\n');editor.innerHTML=`<h3>${esc(m.title)} · Szene ${adminSceneIndex+1}</h3><label>Sprecher<select id="adminSpeaker">${Object.entries(chars).map(([k,c])=>`<option value="${k}" ${k===sc.key?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Gesprochener Text<textarea id="adminText" rows="5">${esc(text(sc.text(state.name||'Teilnehmer')))}</textarea></label><label>Frage<textarea id="adminQuestion" rows="2">${esc(sc.question||'')}</textarea></label><label>Antworten (eine Zeile je Antwort: good|Text oder bad|Text)<textarea id="adminChoices" rows="5">${esc(choices)}</textarea></label><label>Richtige Rückmeldung<textarea id="adminGood" rows="2">${esc(sc.good||'')}</textarea></label><label>Reaktion der Figur<textarea id="adminGuest" rows="3">${esc(sc.guest||'')}</textarea></label><label>Extra-Tipp<textarea id="adminTip" rows="3">${esc(sc.tip||'')}</textarea></label><div class="actions"><button id="adminPreview" class="secondary">▶ Szene testen</button><button id="adminSave" class="primary">Änderungen speichern</button><button id="adminReset" class="ghost-dark">Szene zurücksetzen</button></div>`;document.querySelector('#adminPreview').onclick=()=>speak(document.querySelector('#adminText').value,{characterKey:document.querySelector('#adminSpeaker').value});document.querySelector('#adminSave').onclick=saveEpisodeScene;document.querySelector('#adminReset').onclick=resetEpisodeScene}
function saveEpisodeScene(){const m=modules[adminModuleKey],sc=m?.scenes?.[adminSceneIndex];if(!sc)return;const key=document.querySelector('#adminSpeaker').value;const ov={key,text:document.querySelector('#adminText').value.trim(),question:document.querySelector('#adminQuestion').value.trim(),good:document.querySelector('#adminGood').value.trim(),guest:document.querySelector('#adminGuest').value.trim(),tip:document.querySelector('#adminTip').value.trim(),choices:document.querySelector('#adminChoices').value.split(/\n+/).map(x=>{const p=x.indexOf('|');return p<0?null:[x.slice(p+1).trim(),x.slice(0,p).trim()==='good'?'good':'bad']}).filter(Boolean)};episodeOverrides[adminModuleKey]??=[];episodeOverrides[adminModuleKey][adminSceneIndex]=ov;set('localStorage',EPISODE_OVERRIDE_KEY,JSON.stringify(episodeOverrides));sc.key=key;sc.who=chars[key].name;sc.text=()=>ov.text;sc.question=ov.question||undefined;sc.good=ov.good||undefined;sc.guest=ov.guest||undefined;sc.tip=ov.tip||undefined;sc.choices=ov.choices.length?ov.choices:undefined;document.querySelector('#episodeEditorStatus').textContent='Gespeichert. Die zugehörige Stimme ist bis zur Neuerzeugung als veraltet markiert.';autoRegenerateDialog(`module:${adminModuleKey}:scene:${adminSceneIndex}:main`);if(ov.guest)autoRegenerateDialog(`module:${adminModuleKey}:scene:${adminSceneIndex}:guest`);renderEpisodeEditor()}
function resetEpisodeScene(){if(!episodeOverrides[adminModuleKey])return;delete episodeOverrides[adminModuleKey][adminSceneIndex];set('localStorage',EPISODE_OVERRIDE_KEY,JSON.stringify(episodeOverrides));document.querySelector('#episodeEditorStatus').textContent='Lokale Änderung entfernt. Wirksam nach Neustart der Academy.'}
const ADMIN_REPORT_FILTERS_KEY='kcAcademyAdminReportFiltersV1';
let adminReportFilters=safeParse(get('localStorage',ADMIN_REPORT_FILTERS_KEY,'{}'),{person:'all',period:'all',category:'all',status:'all',device:'all'});
function reportActiveCount(){return Object.values(adminReportFilters).filter(v=>v&&v!=='all').length}
function localLearningRows(){const sum=TelemetryCore.summary(),now=new Date().toISOString(),device=window.KCSupabaseAdapter?.diagnostics?.().deviceName||'Dieses Gerät';const rows=[{participant_id:participantProfile?.id||'local',participant_name:state.name||participantProfile?.displayName||'Unbekannt',device_name:device,last_activity:sum.rows.at(-1)?.at||now,total_minutes:sum.totalMinutes,total_correct:sum.totalCorrect,total_wrong:sum.totalWrong,completed_modules:Object.keys(state.completed).length,total_runs:sum.starts.length,topics:Object.entries(sum.byModule).map(([id,v])=>({id,title:modules[id]?.title||id,...v})),source:'academy'}];const training=window.KCParticipantDataCore?.trainingToRow?.(JSON.parse(localStorage.getItem('kc_training_profile_v0254')||'null'),participantProfile,device);if(training&&training.participant_name!=='Unbekannt'){const i=rows.findIndex(r=>r.participant_id===training.participant_id||r.participant_name===training.participant_name);if(i>=0){rows[i]={...rows[i],total_minutes:Number(rows[i].total_minutes||0)+Number(training.total_minutes||0),total_correct:Number(rows[i].total_correct||0)+Number(training.total_correct||0),total_wrong:Number(rows[i].total_wrong||0)+Number(training.total_wrong||0),completed_modules:Number(rows[i].completed_modules||0)+Number(training.completed_modules||0),total_runs:Number(rows[i].total_runs||0)+Number(training.total_runs||0),last_activity:[rows[i].last_activity,training.last_activity].sort().at(-1),topics:[...(rows[i].topics||[]),...(training.topics||[])],source:'combined'}}else rows.push(training)}return rows}
function periodMatches(date,period){if(period==='all')return true;const age=Date.now()-new Date(date||0).getTime(),day=86400000;if(period==='today')return age<day;if(period==='week')return age<7*day;if(period==='month')return age<31*day;return true}
async function fetchAdminLearningRows(){await window.KCParticipantDataCore?.migrate?.().catch(()=>{});const local=localLearningRows();try{const cloud=await window.KCSupabaseAdapter?.adminLearningReport?.();if(Array.isArray(cloud)&&cloud.length){const map=new Map(local.map(r=>[r.participant_id||r.participant_name,r]));cloud.forEach(r=>map.set(r.participant_id||r.participant_name,{...(map.get(r.participant_id||r.participant_name)||{}),...r,source:'cloud'}));return [...map.values()]}}catch(e){console.warn('Zentrale Adminauswertung nicht verfügbar',e)}return local}
async function renderAdminLearningReport(){const host=document.querySelector('#adminLearningReport');if(!host)return;host.innerHTML='<p class="settings-note">Auswertung wird geladen …</p>';const rows=await fetchAdminLearningRows();const persons=[...new Set(rows.map(r=>r.participant_name).filter(Boolean))].sort(),devices=[...new Set(rows.map(r=>r.device_name).filter(Boolean))].sort();const filtered=rows.filter(r=>(adminReportFilters.person==='all'||r.participant_name===adminReportFilters.person)&&(adminReportFilters.device==='all'||r.device_name===adminReportFilters.device)&&periodMatches(r.last_activity,adminReportFilters.period)&&(adminReportFilters.status==='all'||(adminReportFilters.status==='active'?Number(r.total_minutes)>0:Number(r.completed_modules)>0)));const total=filtered.reduce((a,r)=>({minutes:a.minutes+Number(r.total_minutes||0),correct:a.correct+Number(r.total_correct||0),wrong:a.wrong+Number(r.total_wrong||0),runs:a.runs+Number(r.total_runs||0),completed:a.completed+Number(r.completed_modules||0)}),{minutes:0,correct:0,wrong:0,runs:0,completed:0});const active=reportActiveCount();host.innerHTML=`<div class="admin-report-head"><div><h3>Teilnehmer & Lernstatistik</h3><p class="settings-note">Wer hat wann, wie lange und mit welchem Ergebnis gelernt?</p></div><div class="actions"><button id="participantDataCheck" class="secondary">Teilnehmerdaten prüfen</button><button id="adminReportRefresh" class="secondary">Aktualisieren</button></div></div><div class="admin-report-filters"><label class="${adminReportFilters.person!=='all'?'filter-active':''}">Person<select data-report-filter="person"><option value="all">Alle Personen</option>${persons.map(x=>`<option ${adminReportFilters.person===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label class="${adminReportFilters.period!=='all'?'filter-active':''}">Zeitraum<select data-report-filter="period"><option value="all">Gesamter Zeitraum</option><option value="today" ${adminReportFilters.period==='today'?'selected':''}>Heute</option><option value="week" ${adminReportFilters.period==='week'?'selected':''}>7 Tage</option><option value="month" ${adminReportFilters.period==='month'?'selected':''}>30 Tage</option></select></label><label class="${adminReportFilters.category!=='all'?'filter-active':''}">Thema<select data-report-filter="category"><option value="all">Alle Themen</option>${Object.entries(CATEGORY_DEFS).map(([k,v])=>`<option value="${k}" ${adminReportFilters.category===k?'selected':''}>${esc(v.label)}</option>`).join('')}</select></label><label class="${adminReportFilters.status!=='all'?'filter-active':''}">Status<select data-report-filter="status"><option value="all">Alle</option><option value="active" ${adminReportFilters.status==='active'?'selected':''}>Hat gelernt</option><option value="completed" ${adminReportFilters.status==='completed'?'selected':''}>Folgen abgeschlossen</option></select></label><label class="${adminReportFilters.device!=='all'?'filter-active':''}">Gerät<select data-report-filter="device"><option value="all">Alle Geräte</option>${devices.map(x=>`<option ${adminReportFilters.device===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><button id="adminReportReset" class="filter-toggle ${active?'has-active':''}">Filter zurücksetzen <span>${active} / 5</span></button></div><div class="admin-report-kpis"><article><b>${filtered.length}</b><span>Teilnehmer</span></article><article><b>${Math.round(total.minutes*10)/10} min</b><span>Lernzeit</span></article><article><b>${total.runs}</b><span>Durchgänge</span></article><article><b>${total.correct}</b><span>Richtig</span></article><article><b>${total.wrong}</b><span>Falsch</span></article><article><b>${total.completed}</b><span>Folgen abgeschlossen</span></article></div><div class="admin-report-table-wrap"><table class="admin-report-table"><thead><tr><th>Teilnehmer</th><th>Letzte Aktivität</th><th>Lernzeit</th><th>Durchgänge</th><th>Richtig</th><th>Falsch</th><th>Folgen</th><th>Gerät</th></tr></thead><tbody>${filtered.map(r=>`<tr><td><b>${esc(r.participant_name||'—')}</b><small>${esc(String(r.participant_id||'').slice(0,12))}</small></td><td>${r.last_activity?esc(new Date(r.last_activity).toLocaleString('de-DE')):'—'}</td><td>${Number(r.total_minutes||0).toFixed(1)} min</td><td>${Number(r.total_runs||0)}</td><td>${Number(r.total_correct||0)}</td><td>${Number(r.total_wrong||0)}</td><td>${Number(r.completed_modules||0)}</td><td>${esc(r.device_name||'—')}</td></tr>`).join('')||'<tr><td colspan="8">Keine Daten für diese Filter.</td></tr>'}</tbody></table></div><p class="settings-note">Zentrale Daten aller Teilnehmer erscheinen hier, sobald das Supabase-Superadmin-Konto eingerichtet ist. Bis dahin wird die aktuelle lokale Sitzung angezeigt.</p>`;host.querySelectorAll('[data-report-filter]').forEach(el=>el.onchange=()=>{adminReportFilters[el.dataset.reportFilter]=el.value;set('localStorage',ADMIN_REPORT_FILTERS_KEY,JSON.stringify(adminReportFilters));renderAdminLearningReport()});document.querySelector('#adminReportReset').onclick=()=>{adminReportFilters={person:'all',period:'all',category:'all',status:'all',device:'all'};set('localStorage',ADMIN_REPORT_FILTERS_KEY,JSON.stringify(adminReportFilters));renderAdminLearningReport()};document.querySelector('#adminReportRefresh').onclick=renderAdminLearningReport;document.querySelector('#participantDataCheck').onclick=async()=>{const d=await window.KCParticipantDataCore?.diagnostics?.();alert(`Teilnehmerdaten\nName: ${d?.name||'nicht gefunden'}\nID: ${d?.participantId||'-'}\nLokales Profil: ${d?.profileFound?'JA':'NEIN'}\nHauptschulung: ${d?.trainingFound?'JA':'NEIN'}\nSicherer Speicher: ${d?.secureStorage?'JA':'NEIN'}\nLetzte Aktivität: ${d?.lastActivity||'-'}`)}}
function bindSecretAccess(){const logo=document.querySelector('.brand-logo');if(!logo)return;logo.tabIndex=0;logo.title='';logo.addEventListener('click',()=>{const now=Date.now();adminClickTimes=adminClickTimes.filter(t=>now-t<2500);adminClickTimes.push(now);if(adminClickTimes.length>=7){adminClickTimes=[];openAdminPin()}});logo.addEventListener('pointerdown',()=>{clearTimeout(adminHoldTimer);adminHoldTimer=setTimeout(openAdminPin,5000)});['pointerup','pointerleave','pointercancel'].forEach(e=>logo.addEventListener(e,()=>clearTimeout(adminHoldTimer)))}
function openSettings(){stopSpeech();settingsModal.hidden=false;document.body.classList.add('modal-open');document.querySelector('#modalCoach').value=state.coach;document.querySelector('#modalAddress').value=state.address;document.querySelector('#modalRate').value=state.speechRate;document.querySelector('#modalSubtitles').checked=state.subtitles;document.querySelector('#modalSound').checked=state.sound;document.querySelector('#modalQuizMode').value=state.quizMode;document.querySelector('#modalEpisodeView').value=state.episodeView;document.querySelector('#modalRememberView').checked=state.rememberView;document.querySelector('#modalShuffleAnswers').checked=state.shuffleAnswers;document.querySelector('#modalCountdown').checked=state.countdownEnabled;document.querySelector('#modalAutoContinue').checked=state.autoContinue;document.querySelector('#modalSkipIntroductions').checked=state.skipIntroductions;document.querySelector('#modalOpenLast').checked=state.openLast;document.querySelector('#modalVolume').value=state.volume;document.querySelector('#modalVolumeValue').textContent=`${state.volume}/10`;document.querySelector('#voiceProvider').value=state.voiceProvider;window.KCVoiceProvider?.configure({...elevenConfig,provider:state.voiceProvider});document.querySelector('#designFontScale').value=state.fontScale;document.querySelector('#designReduceMotion').checked=state.reduceMotion;refreshVoiceStudio();refreshCharacterStudio()}
