function stopRecorder(){if(recorderState.mediaRecorder&&recorderState.mediaRecorder.state==='recording')recorderState.mediaRecorder.stop();if(recorderState.stream){recorderState.stream.getTracks().forEach(t=>t.stop());recorderState.stream=null}}
async function startRecording(){try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('Audioaufnahme wird von diesem Browser nicht unterstützt');resetRecorderPreview();const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});recorderState.stream=stream;recorderState.chunks=[];const preferred=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(t=>MediaRecorder.isTypeSupported?.(t));const mr=new MediaRecorder(stream,preferred?{mimeType:preferred}:undefined);recorderState.mediaRecorder=mr;mr.ondataavailable=e=>{if(e.data.size)recorderState.chunks.push(e.data)};mr.onstop=()=>{recorderState.blob=new Blob(recorderState.chunks,{type:mr.mimeType||'audio/webm'});recorderState.url=URL.createObjectURL(recorderState.blob);document.querySelector('#recordPlay').disabled=false;document.querySelector('#recordSave').disabled=false;document.querySelector('#recordingStatus').textContent='Aufnahme bereit – bitte anhören und speichern';if(recorderState.stream){recorderState.stream.getTracks().forEach(t=>t.stop());recorderState.stream=null}};mr.start();document.querySelector('#recordStart').disabled=true;document.querySelector('#recordStop').disabled=false;document.querySelector('#recordingStatus').textContent='● Aufnahme läuft'}catch(err){document.querySelector('#recordingStatus').textContent='Mikrofonzugriff nicht möglich: '+(err?.message||'unbekannter Fehler')}}
function stopRecording(){if(recorderState.mediaRecorder?.state==='recording')recorderState.mediaRecorder.stop();document.querySelector('#recordStart').disabled=false;document.querySelector('#recordStop').disabled=true}
function playRecording(){if(recorderState.url)new Audio(recorderState.url).play()}
async function saveRecording(){if(!recorderState.blob||!recorderState.dialogKey)return;await AudioStore.put(recorderState.dialogKey,recorderState.blob,{character:document.querySelector('#voiceCharacter').value,text:document.querySelector('#voiceText').value});document.querySelector('#recordingStatus').textContent='Aufnahme gespeichert';document.querySelector('#recordDelete').disabled=false}
async function deleteRecording(){if(!recorderState.dialogKey)return;await AudioStore.remove(recorderState.dialogKey);resetRecorderPreview();document.querySelector('#recordDelete').disabled=true;document.querySelector('#recordingStatus').textContent='Aufnahme gelöscht – Gerätestimme wird verwendet'}
function importAudio(file){if(!file||!recorderState.dialogKey)return;resetRecorderPreview();recorderState.blob=file;recorderState.url=URL.createObjectURL(file);document.querySelector('#recordPlay').disabled=false;document.querySelector('#recordSave').disabled=false;document.querySelector('#recordingStatus').textContent='Audiodatei geladen – bitte anhören und speichern'}
function providerDefinition(provider=state.voiceProvider){const defs={elevenlabs:{label:'ElevenLabs',models:[['eleven_multilingual_v2','Multilingual v2'],['eleven_flash_v2_5','Flash v2.5'],['eleven_v3','Eleven v3']],formats:[['mp3_44100_128','MP3 44,1 kHz / 128 kbit']],voicePlaceholder:'Voice-ID aus ElevenLabs',secret:'ELEVENLABS_API_KEY'},openai:{label:'OpenAI TTS',models:[['gpt-4o-mini-tts','GPT-4o mini TTS']],formats:[['mp3','MP3'],['wav','WAV'],['opus','Opus'],['aac','AAC'],['flac','FLAC']],voicePlaceholder:'z. B. coral',secret:'OPENAI_API_KEY'},azure:{label:'Microsoft Azure Speech',models:[['azure-neural','Azure Neural Voice']],formats:[['audio-24khz-48kbitrate-mono-mp3','MP3 24 kHz'],['riff-24khz-16bit-mono-pcm','WAV 24 kHz']],voicePlaceholder:'z. B. de-DE-KatjaNeural',secret:'AZURE_SPEECH_KEY + AZURE_SPEECH_REGION'}};return defs[provider]||defs.elevenlabs}
function refreshProviderForm(){const p=state.voiceProvider,d=providerDefinition(p),s=elevenConfig.providerSettings?.[p]||{};const m=document.querySelector('#elevenModel');if(m){m.innerHTML=d.models.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('');m.value=s.modelId||d.models[0][0]}const f=document.querySelector('#providerOutputFormat');if(f){f.innerHTML=d.formats.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('');f.value=s.outputFormat||d.formats[0][0]}const i=document.querySelector('#providerInstructions');if(i)i.value=s.instructions||'';const v=document.querySelector('#elevenVoiceId');if(v)v.placeholder=d.voicePlaceholder;const sum=document.querySelector('#providerSummary');if(sum)sum.innerHTML=`<b>${d.label}</b><span>Supabase Secret: <code>${d.secret}</code></span><span>Es fehlen nur Supabase-URL, Publishable Key und die feste Stimme je Figur.</span>`;const il=document.querySelector('#providerInstructionsLabel');if(il)il.hidden=p!=='openai'}
function readElevenForm(){elevenConfig.endpoint=document.querySelector('#elevenEndpoint')?.value.trim()||'';elevenConfig.anonKey=document.querySelector('#elevenAnonKey')?.value.trim()||'';const d=providerDefinition(state.voiceProvider),s=elevenConfig.providerSettings[state.voiceProvider]||{};s.modelId=document.querySelector('#elevenModel')?.value||d.models[0][0];s.outputFormat=document.querySelector('#providerOutputFormat')?.value||d.formats[0][0];s.instructions=document.querySelector('#providerInstructions')?.value.trim()||'';elevenConfig.providerSettings[state.voiceProvider]=s;elevenConfig.modelId=s.modelId;elevenConfig.outputFormat=s.outputFormat;elevenConfig.autoGenerate=Boolean(document.querySelector('#elevenAutoGenerate')?.checked);elevenConfig.voiceIds[state.voiceProvider]=elevenConfig.voiceIds[state.voiceProvider]||{};const c=document.querySelector('#voiceCharacter')?.value;if(c)elevenConfig.voiceIds[state.voiceProvider][c]=document.querySelector('#elevenVoiceId')?.value.trim()||'';saveElevenConfig()}
function currentVoiceDialog(){return buildDialogRegistry().find(x=>x.key===document.querySelector('#voiceDialog')?.value)}
function setElevenStatus(message,kind=''){const el=document.querySelector('#elevenStatus');if(!el)return;el.textContent=message;el.className='settings-note'+(kind?` ${kind}`:'')}
async function saveElevenForm(){readElevenForm();setElevenStatus('Provider-Verbindung und feste Stimmenzuordnung wurden lokal gespeichert.','tuv-pass');await refreshVoiceStudio()}
async function testElevenConnection(){
  try{readElevenForm();setElevenStatus('Test läuft …');const dialog=currentVoiceDialog();if(!dialog)throw new Error('Bitte zuerst einen Dialog auswählen.');await generateElevenAudio({...dialog,text:`Dies ist ein Test von ${providerDefinition(state.voiceProvider).label} für die KC FUTURA Stimmen.`},{previewOnly:true});setElevenStatus('Verbindung erfolgreich. Die Teststimme wurde gestartet.','tuv-pass')}
  catch(err){setElevenStatus('Test fehlgeschlagen: '+(err?.message||err),'tuv-fail')}
}
async function generateCurrentVoice(){
  const status=document.querySelector('#recordingStatus');try{readElevenForm();const dialog=currentVoiceDialog();if(!dialog)throw new Error('Kein Dialog ausgewählt.');status.textContent='Stimme wird erzeugt …';status.className='recording-status voice-working';await generateElevenAudio(dialog);setElevenStatus('Sprachdatei erzeugt und verschlüsselt gespeichert.','tuv-pass');await refreshVoiceStudio()}
  catch(err){status.textContent='Erzeugung fehlgeschlagen: '+(err?.message||err);status.className='recording-status voice-stale'}
}
async function generateAllStaleVoices(){
  try{readElevenForm();const registry=buildDialogRegistry();let stale=0,done=0,skipped=0;for(const dialog of registry){const a=await voiceAudioState(dialog);if(a.kind!=='stale')continue;stale++;if(!voiceIdFor(dialog.character)){skipped++;continue}setElevenStatus(`Aktualisierung ${done+1} von ${stale} …`);await generateElevenAudio(dialog);done++}setElevenStatus(`${done} veraltete Stimmen aktualisiert${skipped?`, ${skipped} ohne Voice-ID übersprungen`:''}.`,'tuv-pass');await refreshVoiceStudio()}
  catch(err){setElevenStatus('Sammelaktualisierung abgebrochen: '+(err?.message||err),'tuv-fail')}
}

