function refreshCharacterStudio(){
  const list=document.querySelector('#characterStudioList');if(!list)return;
  list.innerHTML=Object.entries(chars).map(([key,c])=>`<button class="character-studio-item ${key===characterStudioKey?'selected':''}" data-character-edit="${key}"><img src="${AV+c.img}" alt="${c.name}"><span><b>${esc(c.name)}</b><small>${esc(c.role)}</small></span></button>`).join('');
  list.querySelectorAll('[data-character-edit]').forEach(b=>b.onclick=()=>{characterStudioKey=b.dataset.characterEdit;refreshCharacterStudio()});
  const c=chars[characterStudioKey];document.querySelector('#characterStudioImage').src=AV+c.img;document.querySelector('#characterStudioImage').alt=c.name;document.querySelector('#characterStudioName').value=c.name;document.querySelector('#characterStudioRole').value=c.role;document.querySelector('#characterStudioIntro').value=c.intro;
}
function saveCharacterProfile(){const c=chars[characterStudioKey];if(!c)return;c.name=document.querySelector('#characterStudioName').value.trim()||c.name;c.role=document.querySelector('#characterStudioRole').value.trim()||c.role;c.intro=document.querySelector('#characterStudioIntro').value.trim()||c.intro;const all=safeParse(get('localStorage',CHARACTER_OVERRIDE_KEY,'{}'),{});all[characterStudioKey]={name:c.name,role:c.role,intro:c.intro};set('localStorage',CHARACTER_OVERRIDE_KEY,JSON.stringify(all));refreshCharacterStudio();TelemetryCore.event('character_profile_saved',{character:characterStudioKey});autoRegenerateDialog(`character:${characterStudioKey}:intro`)}
