function openRoadmap(){
  stopSpeech();roadmapModal.hidden=false;document.body.classList.add('modal-open');
  const catalog=SceneCore.catalog();const groups={fertig:[], 'in-arbeit':[], geplant:[], idee:[]};
  catalog.forEach(m=>{const key=m.status==='fertig'?'fertig':m.status==='in-arbeit'?'in-arbeit':m.status==='idee'?'idee':'geplant';groups[key].push(m)});
  const completed=catalog.filter(m=>state.completed[m.id]).length;
  const totalScenes=catalog.reduce((n,m)=>n+m.sceneCount,0);const totalQuestions=catalog.reduce((n,m)=>n+m.questionCount,0);
  const render=(title,key,cls)=>`<section class="roadmap-column"><h3>${title}</h3>${groups[key].map(m=>`<article class="roadmap-item ${cls}"><span class="episode-badge">Staffel ${m.season} · Folge ${m.episode}</span><b>${esc(m.title)}</b><small>${esc(m.subtitle)}</small><div class="metadata-strip"><span>${m.sceneCount} Szenen</span><span>${m.questionCount} Fragen</span><span>ca. ${m.estimatedMinutes} Min.</span></div></article>`).join('')||'<p class="settings-note">Keine Einträge.</p>'}</section>`;
  document.querySelector('#roadmapContent').innerHTML=`<div class="roadmap-stats"><div><b>${catalog.length}</b><span>Folgen geplant</span></div><div><b>${catalog.filter(m=>m.ready).length}</b><span>Spielbar</span></div><div><b>${totalScenes}</b><span>Szenen gebaut</span></div><div><b>${totalQuestions}</b><span>Wissensfragen</span></div></div><div class="roadmap-board">${render('Fertig','fertig','ready')}${render('In Arbeit','in-arbeit','progress')}${render('Geplant','geplant','planned')}${render('Ideenspeicher','idee','idea')}</div><div class="actions"><button id="sceneManifestExport" class="secondary">Szenen-Manifest exportieren</button></div>`;
  document.querySelector('#sceneManifestExport').onclick=()=>SceneCore.export();TelemetryCore.event('roadmap_opened');
}
