function dashboardStats(){const sum=TelemetryCore.summary();const ready=Object.entries(modules).filter(([,m])=>m.ready);const completed=ready.filter(([id])=>state.completed[id]).length;const totalAnswers=sum.totalCorrect+sum.totalWrong;const pct=totalAnswers?Math.round(sum.totalCorrect/totalAnswers*100):0;const points=Object.values(state.completed).reduce((n,x)=>n+(Number(x.points)||0),0);return {sum,ready,completed,totalAnswers,pct,points}}
function openDashboard(){stopSpeech();const {sum,ready,completed,totalAnswers,pct,points}=dashboardStats();dashboardModal.hidden=false;document.body.classList.add('modal-open');const moduleRows=ready.map(([id,m])=>{const x=sum.byModule[id]||{};const result=x.answers?Math.round((x.correct||0)/x.answers*100):(state.completed[id]?Math.round((state.completed[id].score||0)/Math.max(1,state.completed[id].total||1)*100):0);return {id,title:m.title,result,runs:x.runs||0,minutes:x.minutes||0,completed:Boolean(state.completed[id])}});const donutCorrect=totalAnswers?pct:0;const finishes=sum.finishes.slice(-10);const plot=finishes.map((f,i)=>({label:`D${i+1}`,value:Number(f.total)?Math.max(0,Math.min(100,Math.round(Number(f.score||0)/Number(f.total)*100))):0,module:modules[f.module]?.title||'Modul'}));const w=420,h=180,padL=42,padR=16,padT=18,padB=38;const x=(i)=>plot.length<2?padL+(w-padL-padR)/2:padL+i*(w-padL-padR)/(plot.length-1);const y=v=>padT+(100-v)*(h-padT-padB)/100;const pointsLine=plot.map((d,i)=>`${x(i)},${y(d.value)}`).join(' ');const maxMinutes=Math.max(1,...moduleRows.map(r=>Number(r.minutes)||0));document.querySelector('#dashboardContent').innerHTML=`<div class="dashboard-kpis"><div><b>${completed}/${ready.length}</b><span>Module abgeschlossen</span></div><div><b>${pct}%</b><span>Richtige Antworten</span></div><div><b>${sum.totalMinutes} Min.</b><span>Lernzeit</span></div><div><b>${points}</b><span>Academy-Punkte</span></div></div><div class="dashboard-grid"><section class="dashboard-card"><h3>Fortschritt nach Themen</h3>${moduleRows.map(r=>`<div class="bar-row"><span>${esc(r.title)}</span><div><i style="width:${r.result}%"></i></div><b>${r.result}%</b></div>`).join('')||'<p>Noch keine Daten.</p>'}</section><section class="dashboard-card"><h3>Antworten</h3><div class="donut" style="--value:${donutCorrect}"><span>${pct}%<small>richtig</small></span></div><p>Richtig: <b>${sum.totalCorrect}</b> · Falsch: <b>${sum.totalWrong}</b></p></section><section class="dashboard-card chart-card"><h3>Lernzeit je Modul</h3><div class="column-chart">${moduleRows.map(r=>`<div title="${esc(r.title)}: ${r.minutes||0} Minuten"><i style="height:${Math.max(8,Math.round((Number(r.minutes)||0)/maxMinutes*112))}px"></i><span>${r.minutes||0}m</span><small>${esc(r.title)}</small></div>`).join('')}</div></section><section class="dashboard-card chart-card"><h3>Lernentwicklung</h3><p class="chart-explain">Richtige Antworten je abgeschlossenem Durchgang. Je höher der Punkt, desto sicherer das Ergebnis.</p><svg class="line-chart meaningful" viewBox="0 0 ${w} ${h}" role="img" aria-label="Lernentwicklung in Prozent"><g class="chart-grid"><line x1="${padL}" y1="${y(100)}" x2="${w-padR}" y2="${y(100)}"/><line x1="${padL}" y1="${y(75)}" x2="${w-padR}" y2="${y(75)}"/><line x1="${padL}" y1="${y(50)}" x2="${w-padR}" y2="${y(50)}"/><line x1="${padL}" y1="${y(25)}" x2="${w-padR}" y2="${y(25)}"/></g><g class="chart-labels"><text x="5" y="${y(100)+4}">100%</text><text x="12" y="${y(75)+4}">75%</text><text x="12" y="${y(50)+4}">50%</text><text x="12" y="${y(25)+4}">25%</text></g>${plot.length?`<polyline points="${pointsLine}" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>${plot.map((d,i)=>`<circle cx="${x(i)}" cy="${y(d.value)}" r="6"><title>${esc(d.module)} · Durchgang ${i+1}: ${d.value}%</title></circle><text x="${x(i)}" y="${h-12}" text-anchor="middle">${i+1}</text>`).join('')}`:`<text x="${w/2}" y="${h/2}" text-anchor="middle">Noch keine abgeschlossenen Durchgänge</text>`}</svg><div class="chart-legend"><span>Y-Achse: richtige Antworten</span><span>X-Achse: Durchgänge</span></div><p>${plot.length?`Letzter Durchgang: <b>${plot.at(-1).value}%</b>. ${plot.length>1?`Veränderung seit dem ersten Durchgang: <b>${plot.at(-1).value-plot[0].value>=0?'+':''}${plot.at(-1).value-plot[0].value} Prozentpunkte</b>.`:''}`:'Starte dein erstes Modul, damit hier deine Entwicklung erscheint.'}</p></section></div><div class="dashboard-recommendation"><h3>Persönliche Empfehlung</h3><p>${pct>=80?'Sehr gut. Vertiefe als Nächstes ein weiteres Thema.':'Wiederhole Themen mit weniger als 80 Prozent, um dein Wissen zu festigen.'}</p></div>`;TelemetryCore.event('dashboard_opened')}
function closeDashboard(){dashboardModal.hidden=true;document.body.classList.remove('modal-open')}


let volumeHideTimer=null;
function syncVolumeUI(){['headerVolume','modalVolume'].forEach(id=>{const e=document.querySelector('#'+id);if(e)e.value=state.volume});['headerVolumeValue','modalVolumeValue'].forEach(id=>{const e=document.querySelector('#'+id);if(e)e.textContent=`${state.volume}/10`})}
function showVolumePopover(){const p=document.querySelector('#volumePopover');if(!p||!state.sound)return;clearTimeout(volumeHideTimer);p.hidden=false;syncVolumeUI()}
function scheduleVolumeHide(){clearTimeout(volumeHideTimer);volumeHideTimer=setTimeout(()=>{const p=document.querySelector('#volumePopover');if(p)p.hidden=true},950)}
function setUserVolume(v){state.volume=Math.max(1,Math.min(10,Number(v)||7));syncVolumeUI();if(VoiceCore.activeAudio)VoiceCore.activeAudio.volume=state.volume/10;if(VoiceCore.activeUtterance)VoiceCore.activeUtterance.volume=Math.max(.1,state.volume/10);saveSettings()}

